import yt_dlp
import deezer
from ytmusicapi import YTMusic

from config import print_log, OUTPUT_FOLDER,illegal_characters


class Downloader():
    # YT-DLP SETTINGS | generated by https://github.com/yt-dlp/yt-dlp/blob/master/devscripts/cli_to_api.py
    # OUTPUT FILE SETTINGS | https://github.com/yt-dlp/yt-dlp#output-template
    DL_SETTINGS = {'final_ext': 'mp3', 'no_warnings': True, 'quiet': True, 'format': 'bestaudio/best',
    'paths': {'home': OUTPUT_FOLDER},
    'postprocessors': [{'key': 'FFmpegExtractAudio',
                        'nopostoverwrites': False,
                        'preferredcodec': 'mp3',
                        'preferredquality': '5'}]}
    

    def download_song(track: deezer.Track, song_id: str) -> dict:
        """
        Takes a deezer.Track object and a song_id and downloads it from YouTube.
        Returns:
            if found/not found (dict): return {"state": True/False, "deezer_track": track}
                - state (bool):
                - deezer_track (deezer.Track):
        """

        settings = Downloader.DL_SETTINGS
        settings["paths"] = {'home': illegal_characters(f"{OUTPUT_FOLDER}/{track.artist.name}/{track.album.title}/")}
        settings["outtmpl"] = {'default': illegal_characters(f'{track.album.artist.name} - {track.title}')}
        downloader = yt_dlp.YoutubeDL(Downloader.DL_SETTINGS)

        try:
            downloader.download(f"https://www.youtube.com/watch?v={song_id}")
            return {"state": True, "deezer_track": track}
        except yt_dlp.utils.DownloadError as e:
            return {"state": False,"deezer_track": track}